import math

def order(a, n):
    """Calculates the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        return None

    phi = n - 1  # Since n is prime, phi(n) = n-1

    # Check divisors of n-1
    for d in range(1, int(math.sqrt(phi)) + 1):
        if phi % d == 0:
            divisors = {d, phi // d}
            for k in divisors:
                if pow(a, k, n) == 1:
                    return k

    # This should theoretically not be reached if a is coprime to n
    return phi

def calculate_C_p(p):
    """Calculates C(p) = (p-1) / ord_p(3) for a prime p != 3."""
    if p == 3:
        return None

    k = order(3, p)
    if k is None:
        # Should not happen for p > 3
        return None

    C_p = (p - 1) // k
    return C_p

def sieve(limit):
    """Generates primes up to limit."""
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p*p, limit + 1, p):
                is_prime[multiple] = False
    return primes

