import math
from collections import defaultdict

def prime_factorization(n):
    factors = defaultdict(int)
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def phi(n):
    if n == 1:
        return 1
    result = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1
    if temp > 1:
        result -= result // temp
    return result

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def order_of_3_mod_k(k):
    """Calculates the multiplicative order of 3 modulo k."""
    if gcd(3, k) != 1:
        return 0 # Should not happen based on problem constraints (3 not dividing m)

    phi_k = phi(k)

    # The order must divide phi(k)
    factors_phi = prime_factorization(phi_k)

    order = phi_k
    for p in factors_phi:
        # Check if order / p is still a valid order
        new_order = order // p
        if pow(3, new_order, k) == 1:
            order = new_order

    return order

def calculate_C_m(m):
    """
    Calculates C(m) using the recursive formula:
    C(m) = sum_{k|m, k>1} C_units(k)
    where C_units(k) = phi(k) / ord_k(3) for gcd(3, k) = 1.
    """

    # Find all divisors of m
    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    # Calculate C_units(k) for k > 1
    sum_C_units = 0
    for k in divisors:
        if k > 1:
            # Since 3 does not divide m, gcd(3, k) must be 1 for all divisors k.
            ord_k_3 = order_of_3_mod_k(k)
            if ord_k_3 > 0:
                C_units_k = phi(k) // ord_k_3
                sum_C_units += C_units_k

    return sum_C_units

